// Minimal Cosmic Dodger implementation
// Assumes an HTML canvas with id="game"

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) {
    console.error('Canvas with id "game" not found');
    return;
  }
  const ctx = canvas.getContext('2d');

  // Full‑screen canvas
  const resize = () => {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  };
  window.addEventListener('resize', resize);
  resize();

  // ----- Game objects -----
  const ship = {
    x: 80,
    y: canvas.height / 2,
    size: 20,
    speed: 4,
    dx: 0,
    dy: 0,
    draw() {
      ctx.fillStyle = '#0f0';
      ctx.beginPath();
      ctx.moveTo(this.x, this.y);
      ctx.lineTo(this.x - this.size, this.y + this.size / 2);
      ctx.lineTo(this.x - this.size, this.y - this.size / 2);
      ctx.closePath();
      ctx.fill();
    },
    update() {
      this.x += this.dx;
      this.y += this.dy;
      // keep within bounds
      this.x = Math.max(this.size, Math.min(canvas.width - this.size, this.x));
      this.y = Math.max(this.size, Math.min(canvas.height - this.size, this.y));
    },
  };

  const asteroids = [];
  const asteroidSpawnInterval = 1500; // ms
  let lastSpawn = 0;

  function spawnAsteroid() {
    const radius = Math.random() * 15 + 10;
    const y = Math.random() * (canvas.height - radius * 2) + radius;
    const speed = Math.random() * 2 + 2 + (score / 30); // increase with score
    asteroids.push({ x: canvas.width + radius, y, radius, speed });
  }

  function updateAsteroids(dt) {
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.x -= a.speed;
      if (a.x + a.radius < 0) asteroids.splice(i, 1);
    }
    // spawn new
    if (performance.now() - lastSpawn > asteroidSpawnInterval) {
      spawnAsteroid();
      lastSpawn = performance.now();
    }
  }

  function drawAsteroids() {
    ctx.fillStyle = '#aaa';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    });
  }

  function drawStars() {
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    // simple star field: 100 random tiny dots each frame
    ctx.fillStyle = '#555';
    for (let i = 0; i < 50; i++) {
      const x = Math.random() * canvas.width;
      const y = Math.random() * canvas.height;
      ctx.fillRect(x, y, 1, 1);
    }
  }

  // ----- Input handling -----
  const keys = {};
  window.addEventListener('keydown', e => {
    keys[e.key] = true;
  });
  window.addEventListener('keyup', e => {
    keys[e.key] = false;
  });

  function handleInput() {
    ship.dx = 0;
    ship.dy = 0;
    if (keys.ArrowUp || keys.w) ship.dy = -ship.speed;
    if (keys.ArrowDown || keys.s) ship.dy = ship.speed;
    if (keys.ArrowLeft || keys.a) ship.dx = -ship.speed;
    if (keys.ArrowRight || keys.d) ship.dx = ship.speed;
  }

  // ----- Collision detection -----
  function checkCollision() {
    for (const a of asteroids) {
      const dist = Math.hypot(ship.x - a.x, ship.y - a.y);
      if (dist < a.radius + ship.size / 2) {
        return true;
      }
    }
    return false;
  }

  // ----- Score -----
  let startTime = performance.now();
  let score = 0;
  function updateScore() {
    score = ((performance.now() - startTime) / 1000).toFixed(1);
  }
  function drawScore() {
    ctx.fillStyle = '#0f0';
    ctx.font = '16px monospace';
    ctx.fillText(`Score: ${score}s`, 10, 20);
  }

  // ----- Main loop -----
  let gameOver = false;
  function loop() {
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#f00';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
      ctx.fillStyle = '#fff';
      ctx.font = '24px sans-serif';
      ctx.fillText(`Final Score: ${score}s`, canvas.width / 2, canvas.height / 2 + 40);
      return;
    }
    const now = performance.now();
    const dt = now - (window.lastTime || now);
    window.lastTime = now;

    drawStars();
    handleInput();
    ship.update();
    updateAsteroids(dt);
    ship.draw();
    drawAsteroids();
    updateScore();
    drawScore();

    if (checkCollision()) {
      gameOver = true;
    }
    requestAnimationFrame(loop);
  }

  requestAnimationFrame(loop);
})();
